async function initialize(){const c=services.config||{},rows={business_name:c.businessName||c.displayName||'Services Piscine Express',intake_enabled:'true'};if(c.contactEmail)rows.contact_email=c.contactEmail;if(c.contactPhone)rows.contact_phone=c.contactPhone;if(c.businessAddress)rows.business_address=c.businessAddress;for(const[k,v]of Object.entries(rows))await db.run('INSERT INTO admin_settings(key,value) VALUES($1,$2) ON CONFLICT(key) DO NOTHING',[k,String(v)]);}
router.use(express.json({limit:'15mb'}));router.use(express.urlencoded({extended:false,limit:'64kb'}));router.use(async(req,res,next)=>{const lang=['fr','en'].includes(req.query.lang)?req.query.lang:(req.cookies&&req.cookies.pwa_lang==='en'?'en':'fr');req.lang=lang;Object.assign(res.locals,{lang,t:{...T[lang]},settings:{},isAdminPage:false,pageTitle:'Services Piscine Express',user:null,currentPath:req.path,field:n=>lang==='en'?n+'_en':n,text:(row,n)=>row[lang==='en'?n+'_en':n]||'',date:d=>d&&Number.isFinite(new Date(d).getTime())?new Intl.DateTimeFormat(lang==='fr'?'fr-CA':'en-CA',{dateStyle:'full',timeStyle:'short',timeZone:'America/Toronto'}).format(new Date(d)):''});try{if(req.query.lang)res.cookie('pwa_lang',lang,{maxAge:31536000000,path:req.tenantPath('/'),sameSite:'lax',secure:true});if(!init)init=initialize().catch(e=>{init=null;throw e;});await init;const settings=Object.fromEntries((await db.all('SELECT key,value FROM admin_settings')).map(r=>[r.key,r.value]));res.locals.settings=settings;for(const[k,v]of Object.entries(settings))if(k.startsWith('text_')&&k.endsWith('_'+lang))res.locals.t[k.slice(5,-lang.length-1)]=v;req.t=res.locals.t;req.settings=settings;res.locals.canonical=req.tenantUrl(req.path);res.locals.structuredData={'@context':'https://schema.org','@type':'Organization',name:settings.business_name,description:req.t.intermediary,url:req.tenantUrl('/')};if(settings._p_hero_image_url&&/^https:\/\//.test(settings._p_hero_image_url))res.locals.structuredData.image=settings._p_hero_image_url;if(services.config.contactPhone)res.locals.structuredData.telephone=services.config.contactPhone;if(services.config.businessAddress)res.locals.structuredData.address={'@type':'PostalAddress',streetAddress:services.config.businessAddress};if(req.path.startsWith('/api/')||req.path.startsWith('/admin')||req.path==='/demandes')res.set('Cache-Control','private, no-store');next();}catch(e){req.t=res.locals.t;next(e);}});
