function admin(req,res,next){if(!services.admin.isAdmin(req))return req.path.startsWith('/api/')?res.status(403).json({error:req.t.forbidden}):res.redirect(req.tenantPath('/admin/login'));if(!['GET','HEAD'].includes(req.method)&&req.get('origin')){try{const host=new URL(req.get('origin')).host;if(host!==new URL(req.tenantOrigin).host)return res.status(403).json({error:req.t.forbidden});}catch(e){return res.status(403).json({error:req.t.forbidden});}}next();}
