function requestErrors(b,t,partner){const e={};for(const k of partner?['company','contact_name','phone','email','municipalities']:['name','phone','municipality','postal_code'])if(!clean(b[k]))e[k]=t.required;const digits=clean(b.phone).replace(/\D/g,'').length;if(digits<10||digits>15)e.phone=t.bad_phone;if(!emailOK(clean(b.email))||clean(b.email).length>254)e.email=t.bad_email;if(!partner&&!/^[GHJ]\d[ABCEGHJ-NPRSTV-Z] ?\d[ABCEGHJ-NPRSTV-Z]\d$/i.test(clean(b.postal_code)))e.postal_code=t.bad_postal;if(b.consent!==true)e.consent=t.consent_required;for(const k of ['name','contact_name','company','municipality'])if(clean(b[k]).length>160)e[k]=t.invalid;for(const k of ['notes','message','municipalities'])if(clean(b[k]).length>2500)e[k]=t.invalid;return e;}
