router.put('/api/admin/settings',wrap(async(req,res)=>{const b=req.body||{},values=b.key?{[clean(b.key)]:b.value}:b.settings||b;if(!values||typeof values!=='object'||Array.isArray(values)||Object.keys(values).length>100)return res.status(422).json({error:req.t.invalid});const pairs=[];for(const[k,v]of Object.entries(values)){const value=clean(v);if(!/^[a-zA-Z0-9_:-]{1,100}$/.test(k)||value.length>15000||(k.endsWith('_url')&&value&&!/^https:\/\/[^\s]+$/.test(value))||(k==='intake_enabled'&&!['true','false'].includes(value))||(k==='contact_email'&&!emailOK(value))||(k==='business_name'&&!value))return res.status(422).json({error:req.t.invalid,fields:{[k]:req.t.invalid}});pairs.push([k,value]);}for(const p of pairs)await db.run('INSERT INTO admin_settings(key,value) VALUES($1,$2) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW()',p);res.json({success:true});}));
router.post('/api/admin/generate-image',wrap(async(req,res)=>{const prompt=clean(req.body.prompt);if(prompt.length<10||prompt.length>2000)return res.status(422).json({error:req.t.invalid});try{res.json({imageUrl:await services.ai.generateImage(prompt,{aspectRatio:['1:1','4:3','16:9','3:2'].includes(req.body.aspectRatio)?req.body.aspectRatio:'4:3'})});}catch(e){res.status(502).json({error:req.t.image_failed});}}));router.post('/api/admin/image',wrap(async(req,res)=>{if(!cloudReady())return res.status(503).json({error:req.t.image_failed});if(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(clean(req.body.data))||clean(req.body.data).length>13981200)return res.status(422).json({error:req.t.photo_type});try{const r=await services.cloudinary.uploader.upload(req.body.data,{folder:services.config.slug+'/content',resource_type:'image'});res.json({imageUrl:r.secure_url});}catch(e){res.status(502).json({error:req.t.image_failed});}}));
async function adminValues(m,b,old,t){const vals={},errors={};for(const f of m.fields){if(f.type==='readonly'||(old&&f.createOnly))continue;let v=b[f.name];if(v===undefined){if(!old&&f.required)errors[f.name]=t.required;continue;}try{if(f.type==='boolean')v=v===true||v===1||v==='1'?1:0;else if(f.type==='number'){v=Number(v);if(!Number.isInteger(v)||v<f.min||v>f.max)throw new Error(t.invalid);}else if(f.type==='checkboxes'){if(typeof v==='string')v=JSON.parse(v);if(!Array.isArray(v)||v.length>100||v.some(x=>!Number.isInteger(Number(x))||Number(x)<1))throw new Error(t.invalid);v=[...new Set(v.map(Number))];const known=new Set(f.options.map(o=>Number(o.value))),prior=new Set(old&&old[f.name]||[]);if(v.some(x=>!known.has(x)&&!prior.has(x)))throw new Error(t.service_required);v=JSON.stringify(v);}else{v=clean(v);if(f.required&&!v)throw new Error(t.required);if(v.length>(f.maxLength||15000))throw new Error(t.invalid);if(f.type==='select'&&!f.options.includes(v))throw new Error(t.invalid);if(['url','image'].includes(f.type)&&v&&!/^https:\/\/[^\s]+$/.test(v))throw new Error(t.invalid);if(f.type==='email'&&!emailOK(v))throw new Error(t.bad_email);if(f.type==='datetime'){if(v&&(!/(Z|[+-]\d\d:\d\d)$/.test(v)||!Number.isFinite(new Date(v).getTime())))throw new Error(t.date_error);v=v||null;}}vals[f.name]=v;}catch(e){errors[f.name]=e instanceof SyntaxError?t.invalid:e.message;}}
const merged={...old,...vals};if(['leads','partners'].includes(m.key)){const n=clean(merged.phone).replace(/\D/g,'').length;if(n<10||n>15)errors.phone=t.bad_phone;if(m.key==='leads'&&!/^[GHJ]\d[ABCEGHJ-NPRSTV-Z] ?\d[ABCEGHJ-NPRSTV-Z]\d$/i.test(clean(merged.postal_code)))errors.postal_code=t.bad_postal;if(merged.consent===1&&(!clean(merged.consent_text)||!merged.consent_at))errors.consent_text=t.consent_proof;if(vals.postal_code)vals.postal_code=vals.postal_code.toUpperCase();}const start=m.key==='callback_slots'?'starts_at':'slot_start',end=m.key==='callback_slots'?'ends_at':'slot_end';if((merged[start]&&!merged[end])||(!merged[start]&&merged[end])||(merged[start]&&new Date(merged[end])<=new Date(merged[start])))errors[end]=t.range_error;if(Object.keys(errors).length){const e=new Error(t.invalid);e.fields=errors;throw e;}if(m.key==='leads'){if(vals.service_ids!==undefined){const ids=JSON.parse(vals.service_ids),before=old&&old.service_ids||[];if(!old||JSON.stringify([...ids].sort())!==JSON.stringify([...before].sort())){const rows=await db.all('SELECT id,name,name_en FROM services WHERE id=ANY($1::int[]) ORDER BY position,id',[ids]);vals.service_names=JSON.stringify(rows.map(s=>({fr:s.name,en:s.name_en})));}}if(old&&(vals.slot_start!==undefined||vals.slot_end!==undefined)){const same=(a,b)=>a||b?new Date(a).getTime()===new Date(b).getTime():true;if(!same(merged.slot_start,old.slot_start)||!same(merged.slot_end,old.slot_end))vals.slot_id=null;}}return vals;}
function adminPage(key,view){return wrap(async(req,res)=>{res.locals.isAdminPage=true;const ms=await getModules(req.lang);res.render(view,{items:await db.all('SELECT * FROM '+key+' ORDER BY created_at DESC,id DESC'),module:ms.find(m=>m.key===key),modules:ms,pageTitle:ms.find(m=>m.key===key).label});});}
function adminList(key){return wrap(async(req,res)=>res.json({[key]:await db.all('SELECT * FROM '+key+' ORDER BY created_at DESC,id DESC')}));}
function adminCreate(key){return wrap(async(req,res)=>{if(key==='uploads'){try{return res.status(201).json({upload:await savePhoto(req,true)});}catch(e){return res.status(e.status||502).json({error:e.status?e.message:req.t.photo_error});}}const m=(await getModules(req.lang)).find(x=>x.key===key);let vals;try{vals=await adminValues(m,req.body||{},null,req.t);}catch(e){if(!e.fields)throw e;return res.status(422).json({error:e.message,fields:e.fields});}if(['leads','partners'].includes(key)){vals.user_id='manual';vals.request_key=services.crypto.randomUUID();vals.language=vals.language||req.lang;if(key==='leads')vals.reference='PE-'+services.crypto.randomBytes(6).toUpperCase();}const names=Object.keys(vals);if(!names.length)return res.status(422).json({error:req.t.invalid});const row=await db.get('INSERT INTO '+key+'('+names.join(',')+') VALUES('+names.map((_,i)=>'$'+(i+1)).join(',')+') RETURNING *',Object.values(vals));res.status(201).json({[m.singular]:row});});}
function adminUpdate(key){return wrap(async(req,res)=>{const old=await db.get('SELECT * FROM '+key+' WHERE id=$1',[req.params.id]);if(!old)return res.status(404).json({error:req.t.not_found});const m=(await getModules(req.lang)).find(x=>x.key===key);let vals;try{vals=await adminValues(m,req.body||{},old,req.t);}catch(e){if(!e.fields)throw e;return res.status(422).json({error:e.message,fields:e.fields});}const names=Object.keys(vals);if(!names.length)return res.json({[m.singular]:old});const row=await db.get('UPDATE '+key+' SET '+names.map((n,i)=>n+'=$'+(i+1)).join(',')+',updated_at=NOW() WHERE id=$'+(names.length+1)+' RETURNING *',[...Object.values(vals),req.params.id]);res.json({[m.singular]:row});});}
function adminDelete(key){return wrap(async(req,res)=>{const old=await db.get('SELECT * FROM '+key+' WHERE id=$1',[req.params.id]);if(!old)return res.status(404).json({error:req.t.not_found});if(key==='uploads')await removePhoto(old);else{if(key==='leads')for(const p of await db.all('SELECT * FROM uploads WHERE lead_id=$1',[old.id]))await removePhoto(p);await db.run('DELETE FROM '+key+' WHERE id=$1',[old.id]);}res.json({success:true});});}
